// --- APP STATE ---
let currentLang = 'sr';
let currentCategory = 'breakfast';

// --- DOM ELEMENTS ---
document.addEventListener('DOMContentLoaded', () => {
  initLanguageSwitcher();
  initMobileMenu();
  initMenuTabs();
  renderMenu(currentCategory);
  setCopyrightYear();
});

function setCopyrightYear() {
  const yEl = document.getElementById('year');
  if (yEl) yEl.textContent = new Date().getFullYear();
}

// Language Switcher Logic
function initLanguageSwitcher() {
  const langBtns = document.querySelectorAll('.lang-btn');
  langBtns.forEach(btn => {
    btn.addEventListener('click', (e) => {
      const lang = e.target.getAttribute('data-lang');
      if (lang && translations[lang]) {
        currentLang = lang;
        langBtns.forEach(b => b.classList.remove('active'));
        e.target.classList.add('active');
        applyTranslations(currentLang);
        renderMenu(currentCategory);
      }
    });
  });
}

function applyTranslations(lang) {
  const dict = translations[lang];
  if (!dict) return;

  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.getAttribute('data-i18n');
    if (dict[key]) {
      el.textContent = dict[key];
    }
  });
}

// Mobile Menu Navigation
function initMobileMenu() {
  const toggleBtn = document.getElementById('menuToggle');
  const mainNav = document.getElementById('mainNav');

  if (toggleBtn && mainNav) {
    toggleBtn.addEventListener('click', () => {
      mainNav.classList.toggle('active');
    });

    // Close menu when clicking links
    mainNav.querySelectorAll('a').forEach(link => {
      link.addEventListener('click', () => {
        mainNav.classList.remove('active');
      });
    });
  }
}

// Menu Category Switcher
function initMenuTabs() {
  const tabBtns = document.querySelectorAll('.tab-btn');
  tabBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      tabBtns.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      const cat = btn.getAttribute('data-cat');
      currentCategory = cat;
      renderMenu(currentCategory);
    });
  });
}

// Render Dynamic Menu Items
function renderMenu(categoryKey) {
  const container = document.getElementById('menuContainer');
  const breakfastNote = document.getElementById('breakfastNote');

  if (!container) return;

  // Toggle breakfast note visibility
  if (breakfastNote) {
    breakfastNote.style.display = (categoryKey === 'breakfast') ? 'inline-block' : 'none';
  }

  const items = menuData[categoryKey] || [];
  container.innerHTML = '';

  items.forEach(item => {
    const name = item.name[currentLang] || item.name['sr'];
    const desc = item.desc[currentLang] || item.desc['sr'];

    const card = document.createElement('div');
    card.className = 'menu-item-card';

    card.innerHTML = `
      <div class="item-top">
        <h3 class="item-title">${escapeHtml(name)}</h3>
        <div class="item-price-box">
          <span class="item-price">${item.price}</span>
          <span class="item-weight">${item.weight}</span>
        </div>
      </div>
      <p class="item-desc">${escapeHtml(desc)}</p>
    `;

    container.appendChild(card);
  });
}

function escapeHtml(str) {
  return str.replace(/[&<>"']/g, function(m) {
    return {
      '&': '&amp;',
      '<': '&lt;',
      '>': '&gt;',
      '"': '&quot;',
      "'": '&#039;'
    }[m];
  });
}